import {RECIPES,resourceCap,productionYield,generatorYield,flightDuration,admissionBio,VERSION,RACES,CATEGORIES,DESTINATIONS,FIELDS,DEFAULTS,scheduledRace,arrivalTicks,newGame,inspect,act,active,occupant,routes,allowedRoutes,energyCap,serialize,restore,validateConfig} from './engine.mjs?v=0.3.0';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toastEl=document.querySelector('#toast');
const KEY='transfer-station-six-shifts-v2';
let state=newGame(),selected={kind:'guest',id:1},loaded=false,storageWarning='',helpChoice=false,settingsDraft=null;
try {const data=localStorage.getItem(KEY);if(!data&&localStorage.getItem('transfer-station-six-shifts-v1'))storageWarning='Новые правила 0.2: начата новая партия. Старое сохранение оставлено отдельно.';if(data){const saved=JSON.parse(data);state=restore(saved.state);selected=saved.selected||selected;loaded=true;}}catch{storageWarning='Сохранение не удалось загрузить. Начата новая партия.';}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(text){toastEl.textContent=text;toastEl.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),4200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify({state:serialize(state),selected}));}catch{toast('Автосохранение недоступно. Выгрузите отчет перед закрытием.');}}
const fmtCost=cost=>Object.entries(cost).filter(([,n])=>n).map(([key,n])=>`${n} ${{energy:'эн.',credits:'кр.',bio:'био',water:'воды'}[key]}`).join(' · ');
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
function command(cmd,label,cls='') {
  const check=inspect(state,cmd);
  return `<button class="action ${cls}" data-cmd="${esc(JSON.stringify(cmd))}" ${check.ok?'':'disabled'}><span class="action-name">${esc(label)}</span><span class="action-meta">${check.ok?`1 такт${fmtCost(check.cost)?' · '+fmtCost(check.cost):''}`:esc(check.reason)}</span></button>`;
}
function avatar(race,variant=0){
  const color=RACES[race].color;
  const body=race==='gas'?'<path d="M23 70Q8 61 21 48Q9 34 28 26Q31 9 47 18Q62 7 70 25Q87 30 79 46Q90 64 74 70Z"/>':race==='water'?'<path d="M49 10Q25 30 22 48Q16 75 49 77Q82 75 77 48Q72 27 49 10Z"/>':'<rect x="22" y="19" width="55" height="56" rx="22"/><path d="M29 24L25 9M70 24L75 10" fill="none" stroke-width="5"/>';
  return `<svg class="alien" viewBox="0 0 100 100" aria-hidden="true"><ellipse cx="50" cy="87" rx="28" ry="5" fill="#0a152b" opacity=".23"/><g fill="${color}" stroke="${color}">${body}</g><rect x="27" y="43" width="46" height="17" rx="8" fill="#213649"/><circle cx="39" cy="51" r="4" fill="#fff"/><circle cx="62" cy="51" r="4" fill="#fff"/><path d="M44 65Q50 ${variant%2?73:69} 57 65" fill="none" stroke="#243b4a" stroke-width="2.5" stroke-linecap="round"/>${race==='water'?'<circle cx="14" cy="30" r="4" fill="#67d5f5" opacity=".5"/><circle cx="84" cy="18" r="6" fill="#67d5f5" opacity=".3"/>':''}</svg>`;
}
function roomArt(medium,p) {
  const color=RACES[medium].color;
  return `<div class="room-art ${medium}"><svg viewBox="0 0 300 160" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="grid-${medium}" width="30" height="25" patternUnits="userSpaceOnUse"><path d="M30 0H0V25" fill="none" stroke="#ffffff" stroke-opacity=".05"/></pattern></defs><rect width="300" height="160" fill="#182c38"/><rect x="16" y="14" width="268" height="126" rx="14" fill="${color}" opacity=".07"/><rect x="22" y="20" width="75" height="52" rx="8" fill="#0b1b29" stroke="${color}" stroke-opacity=".35"/><circle cx="44" cy="38" r="12" fill="${color}" opacity=".35"/><circle cx="72" cy="53" r="2" fill="white"/><circle cx="62" cy="31" r="1" fill="white"/><path d="M0 135H300V160H0Z" fill="url(#grid-${medium})"/><path d="M12 133H288" stroke="${color}" stroke-opacity=".35"/><rect x="229" y="81" width="39" height="48" rx="5" fill="#314852"/><path d="M236 94H259M236 103H251" stroke="${color}" stroke-width="3"/><circle cx="258" cy="118" r="3" fill="${color}"/>${medium==='dry'?'<path d="M53 131V103M52 116Q25 96 42 92Q56 94 53 111Q75 86 79 101Q75 114 54 117" fill="#98bf8c" stroke="#98bf8c"/><path d="M40 123H66L61 135H45Z" fill="#987959"/>':medium==='water'?'<path d="M0 113Q40 101 80 113T160 113T240 113T320 113V160H0Z" fill="#67d5f5" opacity=".15"/><circle cx="61" cy="94" r="7" stroke="#67d5f5" fill="none" opacity=".5"/><circle cx="78" cy="78" r="3" fill="#67d5f5" opacity=".5"/>':'<ellipse cx="80" cy="103" rx="55" ry="15" fill="#c4a1fa" opacity=".14"/><ellipse cx="180" cy="61" rx="60" ry="13" fill="#c4a1fa" opacity=".1"/>'}</svg>${p?`<div class="room-alien">${avatar(p.race,p.id)}</div>`:'<span class="empty-room">Свободная комната</span>'}</div>`;
}
function resource(label,value,max,symbol,cls='') {return `<div class="resource ${cls}"><span class="res-icon">${symbol}</span><div><small>${label}</small><strong>${value}${max?`<em> / ${max}</em>`:''}</strong></div></div>`;}
function patienceBar(p){return `<div class="patience ${p.remaining<=4?'urgent':''}"><span>${p.status==='queue'?'Терпение в очереди':'Срок размещения'}: ${p.remaining} / ${p.patienceMax}</span><div role="progressbar" aria-label="${p.status==='queue'?'Терпение':'Срок размещения'} ${esc(p.name)}" aria-valuenow="${p.remaining}" aria-valuemin="0" aria-valuemax="${p.patienceMax}"><i style="width:${Math.max(0,p.remaining/p.patienceMax*100)}%"></i></div></div>`;}
function guestCard(p){return `<button class="guest-card ${selected.kind==='guest'&&selected.id===p.id?'selected':''}" data-select="guest:${p.id}">${avatar(p.race,p.id)}<div class="guest-info"><strong>${esc(p.name)} ${p.story?'<span class="story-star" title="Именной пассажир">✦</span>':''}</strong><span>${RACES[p.race].name} · ${CATEGORIES[p.category]}</span><div class="tags">${tag(RACES[p.race].medium)}${tag(`${p.bioNeed} био`)}${tag(p.status==='room'?'Комната '+(p.room+1):p.extra?'Вне расписания':'В очереди')}</div>${patienceBar(p)}<span class="card-link">Требования пассажира →</span></div></button>`;}
function selectedPassenger(){if(selected.kind==='guest')return state.guests.find(p=>p.id===selected.id&&['queue','room'].includes(p.status));if(selected.kind==='room')return occupant(state,selected.id);}
function storyText(p) {
  if(!p.story)return '';
  let text;
  if(p.story==='neri')text=p.visit===1?'«Везу семена океанских садов. Контейнер треснул… Если найдется немного биоматериала, они переживут дорогу».':state.stories.neri.helped?'«Ваш контейнер спас весь урожай. Я привез материал для станции!» После отправки: +20 био, в пределах склада.':'«Семена не доехали. Теперь перевожу камни. Они хотя бы не жалуются». Новая поездка — новый шанс.';
  else text=p.visit===1?'«Весь дипломатический архив здесь. Да, бумажный. Да, в пакете. Можно добавить упаковку?»':'«Архив снова со мной. Не спрашивайте почему». '+(state.stories.ro.helped?'За прошлую помощь после отправки: +8 кредитов.':'Документы восстанавливали по памяти. Получился сборник стихов.');
  return `<div class="story"><span>✦ ${p.visit===1?'Первая встреча':'Снова знакомое лицо'}</span><p>${esc(text)}</p></div>`;
}
function passengerRequirements(p) {
  const freeRooms=state.rooms.map((medium,i)=>medium===p.race&&!occupant(state,i)?i+1:null).filter(Boolean);
  const accommodated=p.status==='room';
  const discounts=freeRooms.map(n=>admissionBio(state,p,n-1));const need=accommodated?state.log.find(e=>e.command.type==='accept'&&e.command.guest===p.id)?.cost.bio??p.bioNeed:discounts.length?Math.min(...discounts):p.bioNeed;
  const roomStatus=accommodated?`Размещен в комнате ${p.room+1}`:freeRooms.length?`Подходит комната ${freeRooms.join(' или ')}`:'Свободной подходящей комнаты нет — нужна подготовка';
  const routeRule=p.category===0?'Любое открытое направление':p.category===1?'Одно из указанных направлений':'Только указанное направление';
  const request=(label,status,done=false)=>`<li class="service-request ${done?'fulfilled':''}"><span aria-hidden="true">${done?'✓':'○'}</span><div><b>${esc(label)}</b><small>${esc(status)}</small></div></li>`;
  let extra='';
  if(p.story&&p.visit===1){
    const title=p.story==='neri'?'Починить контейнер с семенами':'Упаковать бумажный архив';
    const price=p.story==='neri'?'2 био':'4 кр.';
    const status=p.route?(p.help?'Услуга оказана':'Дополнительная услуга не выбрана'):helpChoice&&accommodated?`Выбрано · ${price} при подтверждении маршрута`:`По желанию · ${price} · выбрать при оформлении маршрута`;
    extra=request(title,status,!!p.route&&p.help);
  }
  return `<section class="passenger-requirements" aria-label="Требования пассажира"><h3>Требования пассажира</h3><div class="requirement-section"><h4>Условия содержания</h4><p><strong>${RACES[p.race].medium} среда</strong> · отдельная комната, 1 место</p><p class="requirement-note">Биоматериал: <strong>${need} ед.</strong> · ${accommodated?'уже оплачен':'однократно при приеме'}</p>${patienceBar(p)}${p.race==='water'?`<p class="requirement-note">На прием требуется ${state.cfg.acceptWater} ед. воды.</p>`:''}<p class="requirement-status ${accommodated||freeRooms.length?'ready':'attention'}">${accommodated?'✓':'○'} ${esc(roomStatus)}</p></div><div class="requirement-section"><h4>Направление следования</h4><p class="requirement-note">${routeRule}</p><div class="requested-routes">${allowedRoutes(state,p).map(key=>`<span class="requested-route ${p.route===key?'chosen':''}">${key} · ${DESTINATIONS[key]}${p.route===key?' ✓':''}</span>`).join('')}</div><p class="requirement-status ${p.route?'ready':''}">${p.route?`Подтверждено: ${p.route} · ${DESTINATIONS[p.route]}`:'Маршрут еще не оформлен'}</p></div><div class="requirement-section"><h4>Запрос услуг станции</h4><ul class="service-requests">${request('Временное размещение',accommodated?'Пассажир размещен':'Ожидает приема',accommodated)}${request('Оформление маршрута',p.route?'Направление подтверждено':'Требуется подтверждение',!!p.route)}${request('Отправка следующим рейсом',p.route?'Маршрут готов, ожидает отправки':'После размещения и оформления маршрута')}${extra}</ul>${extra?'':'<p class="requirement-note">Дополнительных запросов нет.</p>'}</div></section>`;
}

const ui={page:'passengers',room:0,route:'A',workTab:'Ресурсы',upgradeTab:'Генераторы',recipe:'ration',producer:'bio',rest:1,dialog:{},noticeRead:0,manifest:[]};
const PAGES=[['passengers','◎','Пассажиры'],['rooms','▦','Комнаты'],['routes','↗','Рейсы'],['workshop','⚒','Мастерская'],['upgrades','↑','Улучшения'],['supply','＋','Снабжение'],['rest','☾','Отдых']];
const WORLDS={dry:'Терра',water:'Пелагия',gas:'Нефела'};
const ROUTE_INFO={A:'Аврора — ближайший пересадочный узел и спокойный старт дальнейшего пути.',B:'Борея — научные поселения среди холодных океанов.',C:'Церера — торговые станции внешнего сектора.'};
const navButton=(page,label,cls='')=>`<button class="button ${cls}" data-page="${page}">${label}</button>`;
const empty=(title,text)=>`<div class="empty-state"><span>◎</span><h2>${title}</h2><p>${text}</p></div>`;
const forecast=()=>'<div class="forecast" id="forecast"><b>Предпросмотр действия</b><span>Наведите на действие или выберите его клавишей Tab.</span></div>';
const tabs=(kind,values,current)=>`<div class="tabs" aria-label="Категории">${values.map(v=>`<button data-tab="${kind}:${v}" aria-pressed="${v===current}" class="${v===current?'active':''}">${v}</button>`).join('')}</div>`;
function currentGuest(){const p=selectedPassenger()||active(state)[0];if(p&&selected.id!==p.id){selected={kind:'guest',id:p.id};helpChoice=false;}return p;}
function statusLabel(p){return p.status==='queue'?'Ожидает приема':p.status==='room'?`Комната ${p.room+1}`:p.status==='flight'?'В полете':'Поездка завершена';}
function header(){return `<header class="global-header"><div class="masthead"><div class="brand"><div class="brand-mark">↗</div><div><h1>ПЕРЕСАДОЧНАЯ</h1><span>Сектор 07 · станция Земля</span></div></div><div class="shift-status"><b>Смена ${state.shift} / 6</b><span>${state.ended?'Завершена':`Рабочий такт ${state.tick+1} / ${state.cfg.shiftTicks}`}</span></div><div class="header-actions"><button class="button" data-action="notifications">Сообщения <b>${notifications().length}</b></button><button class="button" data-action="journal">События</button><button class="button" data-action="settings-menu">Настройки</button></div></div><div class="resource-bar" aria-label="Ресурсы станции">${resource('Такт',state.world+1,null,'◷')}${resource('Кредиты',state.credits,null,'◈','gold')}${resource('Энергия',state.energy,energyCap(state),'ϟ','yellow')}${resource('Биоматериал',state.bio,resourceCap(state,'bio'),'✳','green')}${resource('Вода',state.water,resourceCap(state,'water'),'◉','blue')}${resource('Опыт',state.xp,null,'✦','purple')}<button class="resource rep-resource" data-action="reputation"><span class="res-icon">◇</span><div><small>Репутация рас</small><strong>${state.rep.dry}<em> / </em>${state.rep.water}<em> / </em>${state.rep.gas}</strong><small>Терраны / Аквари / Аэриды</small></div></button></div></header>`;}
function sideNav(){return `<aside class="sidebar"><div><span class="eyebrow">Управление станцией</span><nav aria-label="Разделы станции">${PAGES.map(([id,icon,title])=>`<button data-page="${id}" ${ui.page===id?'aria-current="page"':''}><span>${icon}</span>${title}${id==='passengers'?`<b>${active(state).length}</b>`:''}</button>`).join('')}</nav></div><div class="sidebar-bottom"><span class="eyebrow">План отправок</span><strong>${state.sent}<span> / ${state.cfg.target}</span></strong><div class="bar"><i style="width:${Math.min(100,state.sent/state.cfg.target*100)}%"></i></div><p>${Math.max(0,state.cfg.target-state.sent)} до выполнения плана</p><button class="button" data-action="help">Как играть</button><small>Прототип 0.3 · автосохранение</small></div></aside>`;}
function pageHeading(title,sub,extra=''){return `<div class="page-heading"><div><span class="eyebrow">Земля / операционная палуба</span><h2>${title}</h2><p>${sub}</p></div>${extra}</div>`;}
function eventFeed(){const events=state.log.flatMap(e=>e.events.filter(x=>!x.startsWith('Батарея:')).map(text=>({text,tick:e.world}))).slice(-4).reverse();return `<section class="recent-events"><div class="section-heading"><h3>Последние события</h3><button class="text-button" data-action="journal">Все события →</button></div>${events.length?events.map(e=>`<div><span>Такт ${e.tick}</span><p>${esc(e.text)}</p></div>`).join(''):'<p class="muted">Станция открыта. Пассажиры ожидают приема.</p>'}</section>`;}
function passengerPage(){const list=active(state),p=currentGuest();if(p&&selected.kind!=='guest')selected={kind:'guest',id:p.id};return `${pageHeading('Пассажиры','Разместите гостя, согласуйте маршрут и отправьте следующим рейсом.',tag(`${state.guests.filter(g=>g.status==='queue').length} / ${state.cfg.queueCap} в очереди`))}<div class="passenger-layout"><section class="panel passenger-list"><div class="section-heading"><h3>На станции</h3><span>${list.length}</span></div><div class="guest-list">${list.length?list.map(guestCard).join(''):empty('Все обслужены','Проверьте расписание или подготовьте станцию.')}</div><button class="button full" data-action="newest" ${list.length?'':'disabled'}>Прибыл новый · показать последнего ↓</button><details class="schedule"><summary>Расписание и поток</summary><p>Плановый гость каждые ${state.cfg.arrivalPeriod} такта; дополнительно: ${state.cfg.extraOne}% — один, ${state.cfg.extraTwo}% — двое.</p>${arrivalTicks(state.shift,state.cfg).map((t,i)=>`<div class="arrival"><span>${RACES[scheduledRace(state.shift,i)].name}</span><b>${t<=state.tick+1?'прибыл':'такт '+t}</b></div>`).join('')}</details></section><section class="panel passenger-detail">${p?passengerInfo(p):empty('Выберите пассажира','В этой панели появятся требования и доступные действия.')}</section><aside class="dialog-column">${p?dialogue(p):'<section class="panel">'+empty('Связь открыта','Здесь появится диалог с выбранным гостем.')+'</section>'}${eventFeed()}</aside></div>`;}
function passengerInfo(p){return `<div class="person-heading">${avatar(p.race,p.id)}<div><span class="eyebrow">Личное дело / ${String(p.id).padStart(3,'0')}</span><h2>${esc(p.name)} ${p.story?'✦':''}</h2><p>${RACES[p.race].name} · ${CATEGORIES[p.category]}</p></div></div><div class="facts"><div><span>Родной мир</span><b>${WORLDS[p.race]}</b></div><div><span>Статус</span><b>${statusLabel(p)}</b></div><div><span>Личное отношение</span><b>${p.relation||0}</b></div><div><span>Оплата после прибытия</span><b class="gold">${state.cfg['reward'+p.category]} кр.</b></div></div>${passengerRequirements(p)}<div class="passenger-actions"><button class="button primary" data-action="choose-room" ${p.status==='queue'?'':'disabled'}>Выбрать комнату</button><button class="button ${p.status==='room'?'primary':''}" data-action="choose-route" ${p.status==='room'?'':'disabled'}>Выбрать пункт назначения</button></div>${p.status==='queue'?command({type:'refuse',guest:p.id},'Отказать в приеме · −1 репутация','quiet'):''}${p.category===3&&p.status==='room'?command({type:'trade',guest:p.id},'Купить у торговца 30 био за 10 кр.') :''}${forecast()}`;}
function dialogue(p){const answer=ui.dialog[p.id];return `<section class="panel dialogue"><div class="section-heading"><h3>Диалог</h3>${tag('Связь установлена','open')}</div><div class="speaker">${avatar(p.race,p.id)}<b>${esc(p.name)}</b></div>${p.story?storyText(p):`<div class="speech"><p>«Мне нужна ${RACES[p.race].medium.toLowerCase()} комната. ${p.status==='queue'?'Надеюсь, очередь скоро подойдет.':'Спасибо за размещение. Поможете с дальнейшим рейсом?'}»</p></div>`}${answer?`<div class="reply"><span>Ответ пассажира</span><p>${esc(answer)}</p></div>`:''}<div class="dialogue-options"><button class="button" data-talk="needs">Что вам необходимо?</button><button class="button" data-talk="route">Куда вы направляетесь?</button>${p.story&&p.visit===1&&!p.route?`<button class="button ${helpChoice?'chosen':''}" data-action="help-story">${helpChoice?'✓ Помощь выбрана':'Предложить помощь'} · ${p.story==='neri'?'2 био':'4 кр.'}</button><p class="hint">Стоимость спишется вместе с оформлением маршрута. ${helpChoice?'Нажмите повторно, чтобы отменить.':''}</p>`:''}</div><div class="inventory-help"><h3>Помочь предметом</h3>${command({type:'useItem',guest:p.id,item:p.status==='queue'?'ration':'comfort'},p.status==='queue'?`Дать паек · в запасе ${state.inventory.ration}`:`Набор комфорта · в запасе ${state.inventory.comfort}`)}${navButton('workshop','Изготовить в мастерской →','quiet')}</div></section>`;}
function roomCard(m,i,p,mode='select'){return `<button class="room ${ui.room===i?'selected':''}" data-room="${i}" aria-pressed="${ui.room===i}"><div class="room-heading"><b>Комната ${String(i+1).padStart(2,'0')}</b>${tag('Ур. '+state.roomLevels[i])}</div>${roomArt(m,p)}<div class="room-footer"><strong>${RACES[m].medium} среда</strong><span>${p?`${esc(p.name)} · ${p.remaining} такт.`:'Свободна · 1 место'}</span></div></button>`;}
function roomsPage(){const i=Math.min(ui.room,state.rooms.length-1),p=occupant(state,i);ui.room=i;const waiting=currentGuest();return `${pageHeading('Комнаты','Подготовьте среду и разместите пассажиров.',tag(`${state.guests.filter(p=>p.status==='room').length} / ${state.rooms.length} мест занято`))}<div class="two-column"><section><div class="rooms">${state.rooms.map((m,i)=>roomCard(m,i,occupant(state,i))).join('')}</div><div class="panel build-room"><div><h3>Расширение станции</h3><p>${state.rooms.length} / ${state.cfg.maxRooms} комнат · новая комната — 1 место</p></div><button class="button" data-action="build-room" ${state.rooms.length>=state.cfg.maxRooms?'disabled':''}>Построить новую комнату</button><p class="hint">${state.cfg.buildPrice} кр. · ${state.cfg.buildBio} био · ${state.cfg.upgradeEnergy} эн. · нужно ${state.cfg.buildXP} XP</p></div></section><aside class="panel detail-panel"><span class="eyebrow">Выбранная комната</span><h2>Комната ${i+1}</h2><p>${RACES[state.rooms[i]].medium} среда · уровень ${state.roomLevels[i]} · ${p?'занята':'свободна'}</p><button class="button full" data-action="room-info">Подробная информация</button>${p?`<div class="info-box">${esc(p.name)} · осталось ${p.remaining} такт.</div><button class="button primary full" data-guest="${p.id}">Открыть пассажира →</button>`:waiting?.status==='queue'?`<h3>Прием: ${esc(waiting.name)}</h3>${command({type:'accept',guest:waiting.id,room:i},'Разместить выбранного пассажира','primary')}`:''}<h3>Перестроить среду</h3>${Object.keys(RACES).map(m=>command({type:'convert',room:i,medium:m},RACES[m].medium+' комната')).join('')}<h3>Улучшить комнату</h3><p class="hint">Уровень 2: −1 био на прием (минимум 1), +2 такта размещения.</p>${command({type:'roomUpgrade',room:i},'Повысить до уровня 2')}${forecast()}</aside></div>`;}
function routeCandidates(){return state.guests.filter(p=>p.status==='room'&&p.route===ui.route);}
function routesPage(){const available=routes(state),p=currentGuest();const assigned=routeCandidates();ui.manifest=ui.manifest.filter(id=>assigned.some(p=>p.id===id));const departures=state.flights.filter(f=>f.remaining>0);return `${pageHeading('Рейсы','Оформляйте маршруты и объединяйте пассажиров одного направления.') }<div class="route-layout"><section class="route-list">${Object.entries(DESTINATIONS).map(([key,name])=>`<button class="route-card ${ui.route===key?'selected':''}" data-route="${key}" aria-pressed="${ui.route===key}"><span class="planet planet-${key}"></span><div><h3>${key} · ${name}</h3><p>${flightDuration(key)} такт. в пути</p><small>${available.includes(key)?'Направление открыто':`Нужно ${key==='B'?state.cfg.bXP:state.cfg.cXP} XP`}</small></div></button>`).join('')}<div class="panel"><h3>В полете</h3>${departures.length?departures.map(f=>`<p>Рейс ${f.route} · ${f.guests.length} пасс.<br><span class="muted">Прибытие через ${f.remaining} такт.</span></p>`).join(''):'<p class="muted">Нет активных рейсов</p>'}</div></section><section class="panel route-details"><span class="eyebrow">Пункт назначения</span><h2>${DESTINATIONS[ui.route]}</h2><div class="route-illustration"><span class="planet planet-${ui.route}"></span><span class="flight-line">········ ↗ ········</span><span class="station-glyph">▦</span></div><p>${ROUTE_INFO[ui.route]}</p><div class="facts"><div><span>Перелет</span><b>${flightDuration(ui.route)} такт.</b></div><div><span>Отправление</span><b>Такт ${state.world+1}</b></div><div><span>На пассажира</span><b>${state.cfg.sendEnergy} энергии</b></div><div><span>Требования</span><b>Комната + маршрут</b></div></div><p class="hint">Отправление занимает 1 такт, включенный в перелет. Оплата и опыт начисляются по прибытии. Комнаты освобождаются сразу.</p><h3>Оформление маршрута</h3>${p?`<p>Выбран: <b>${esc(p.name)}</b> · ${statusLabel(p)}</p>${command({type:'route',guest:p.id,route:ui.route,help:!p.route&&helpChoice},p.route===ui.route?'Маршрут уже оформлен':'Подтвердить направление','primary')}${p.status==='queue'?navButton('rooms','Сначала разместить пассажира →'):''}`:'<p class="muted">Выберите пассажира, чтобы оформить маршрут.</p>'}${forecast()}</section><aside class="panel manifest"><div class="section-heading"><h3>Пассажиры рейса</h3>${tag(ui.manifest.length+' выбрано')}</div>${assigned.length?assigned.map(p=>`<label class="manifest-person"> <input type="checkbox" data-manifest="${p.id}" ${ui.manifest.includes(p.id)?'checked':''}>${avatar(p.race,p.id)}<span><b>${esc(p.name)}</b><small>${p.remaining} такт. в комнате</small></span></label>`).join(''):empty('Список пуст','Добавьте размещенного гостя и оформите ему это направление.')}<button class="button full" data-action="add-passenger">Добавить пассажира</button><div class="flight-total"><span>Стоимость рейса</span><strong>${ui.manifest.length*state.cfg.sendEnergy} энергии</strong></div>${command({type:'depart',guests:ui.manifest},'Отправить рейс','primary')}<p class="hint">Один рейс — одно направление. Выберите галочками, кто полетит сейчас.</p></aside></div>`;}
function workshopPage(){const isResources=ui.workTab==='Ресурсы',recipes=ui.workTab==='Предметы'?['ration','comfort']:ui.workTab==='Оборудование'?['cell']:[];const r=RECIPES[ui.recipe];return `${pageHeading('Мастерская','Производите ресурсы и предметы для помощи пассажирам.')}${tabs('work',['Предметы','Оборудование','Ресурсы','Другое'],ui.workTab)}<div class="two-column"><section class="catalog-grid">${isResources?['bio','water'].map(k=>`<button class="catalog-card ${ui.producer===k?'selected':''}" data-producer="${k}"><span class="catalog-icon ${k==='bio'?'green':'blue'}">${k==='bio'?'✳':'◉'}</span><h3>${k==='bio'?'Биосинтезатор':'Водосборник'}</h3><p>+${productionYield(state,k)} / ${state.cfg.period} такта</p>${tag(state.production[k]?'Работает':'Выключен',state.production[k]?'open':'')}</button>`).join(''):recipes.length?recipes.map(k=>`<button class="catalog-card ${ui.recipe===k?'selected':''}" data-recipe="${k}"><span class="catalog-icon">${k==='ration'?'▣':k==='comfort'?'✦':'ϟ'}</span><h3>${RECIPES[k].name}</h3><p>${RECIPES[k].description}</p><small>${k==='cell'?'Пополняет заряд':`В наличии: ${state.inventory[k]} / 5`}</small></button>`).join(''):`<div class="panel">${empty('Особые заказы','Личные просьбы Нери и Ро доступны в диалоге с пассажиром.')}${navButton('passengers','Открыть пассажиров →')}</div>`}</section><aside class="panel detail-panel">${isResources?productionDetail(ui.producer):recipes.length?`<span class="eyebrow">Рецепт</span><h2>${r.name}</h2><p>${r.description}</p><h3>Необходимые ресурсы</h3><div class="cost-box">${fmtCost(r.cost)} · 1 такт</div>${command({type:'craft',recipe:ui.recipe},'Создать','primary')}<p class="hint">${ui.recipe==='cell'?'Заряд сразу поступит в батарею.':'Готовый предмет можно дать гостю в его диалоге; применение занимает 1 такт и улучшает личное отношение на 2.'}</p>`:`<h2>Индивидуальные услуги</h2><p>Стоимость и условия запроса указаны в карточке пассажира. Решение подтверждается при оформлении маршрута.</p>`}${forecast()}</aside></div>`;}
function productionDetail(k){return `<span class="eyebrow">Производство · уровень ${state.factoryLevels[k]}</span><h2>${k==='bio'?'Биосинтезатор':'Водосборник'}</h2><p>+${productionYield(state,k)} ${k==='bio'?'биоматериала':'воды'} каждые ${state.cfg.period} такта.</p><div class="facts"><div><span>Стоимость выпуска</span><b>${state.cfg.productionEnergy} энергии</b></div><div><span>Запас / склад</span><b>${state[k]} / ${resourceCap(state,k)}</b></div><div><span>Следующее окно выпуска</span><b>Через ${state.cfg.period-state.world%state.cfg.period} такт.</b></div></div>${command({type:'toggle',resource:k,on:!state.production[k]},state.production[k]?'Остановить производство':'Запустить производство','primary')}<p class="hint">Включение занимает 1 такт. Выпуск автоматический, в том числе во сне; без места или энергии партия пропускается.</p>`;}
function upgradesPage(){const tab=ui.upgradeTab;return `${pageHeading('Улучшения','Сравните эффект и стоимость до покупки.')}${tabs('upgrade',['Генераторы','Комнаты','Станция','Другое'],tab)}<div class="upgrade-grid">${tab==='Генераторы'?['power','bio','water'].map(k=>`<section class="panel upgrade-card"><span class="catalog-icon">${k==='power'?'ϟ':k==='bio'?'✳':'◉'}</span><h2>${k==='power'?'Генератор энергии':k==='bio'?'Биосинтезатор':'Водосборник'}</h2><p>${k==='power'&&!state.upgrades.generator?'Не установлен':`Уровень ${state.factoryLevels[k]} / 3`}</p><div class="effect"><span>Сейчас</span><b>+${k==='power'?(state.upgrades.generator?generatorYield(state):0):productionYield(state,k)} / ${k==='power'?state.cfg.generatorPeriod:state.cfg.period} такта</b><span>После улучшения</span><b>${state.factoryLevels[k]>=3?'Максимум':`+${k==='power'?(state.upgrades.generator?generatorYield(state)+2:state.cfg.generatorYield):productionYield(state,k)+(k==='bio'?3:2)}`}</b></div>${k==='power'&&!state.upgrades.generator?command({type:'upgrade',upgrade:'generator'},'Установить генератор','primary'):command({type:'factoryUpgrade',resource:k},'Улучшить производство','primary')}<p class="hint">${k==='power'?'Каждый выпуск расходует 1 топливо. Заправка — в снабжении.':`Каждый выпуск стоит ${state.cfg.productionEnergy} энергии.`}</p></section>`).join(''):tab==='Комнаты'?`<section class="panel"><h2>Новые жилые модули</h2><p>Сейчас ${state.rooms.length} / ${state.cfg.maxRooms}. Каждая комната добавляет одно место.</p><button class="button primary full" data-action="build-room">Построить новую комнату</button></section><section class="panel"><h2>Уровень комнат</h2><p>Уровень 2 снижает расход на прием на 1 био и добавляет 2 такта размещения.</p>${navButton('rooms','Выбрать комнату →','full')}</section>`:tab==='Станция'?['capacity','storage'].map(k=>`<section class="panel"><h2>${k==='capacity'?'Накопитель энергии':'Расширение склада'}</h2><p>${k==='capacity'?`${state.cfg.energyCap} → ${state.cfg.energyCap+state.cfg.extraCapacity} энергии`:`Био: ${state.cfg.bioCap} → ${state.cfg.bioCap+state.cfg.bioExtra}; вода: ${state.cfg.waterCap} → ${state.cfg.waterCap+state.cfg.waterExtra}`}</p>${command({type:'upgrade',upgrade:k},state.upgrades[k]?'Установлено':'Установить улучшение','primary')}</section>`).join(''):`<section class="panel"><h2>Экономная перестройка</h2><p>Расход биоматериала на изменение среды: ${state.cfg.convertBio} → ${state.cfg.convertBio-state.cfg.efficientSaving}.</p>${command({type:'upgrade',upgrade:'efficient'},state.upgrades.efficient?'Установлено':'Установить улучшение','primary')}</section>`}</div>${forecast()}`;}
function supplyPage(){return `${pageHeading('Пополнение ресурсов','Покупка занимает один такт. Производство и очередь продолжают работать.')}<div class="supply-grid">${[['battery','Заряд батареи','ϟ',state.cfg.batterySize,state.cfg.batteryPrice],['bioPack','Биоматериал','✳',state.cfg.bioPack,state.cfg.bioPrice],['waterPack','Вода','◉',state.cfg.waterPack,state.cfg.waterPrice]].map(([type,name,icon,size,price])=>`<section class="panel"><span class="catalog-icon">${icon}</span><h2>${name}</h2><p>${type==='battery'?`Заряд ${state.reserve} / ${state.cfg.reserveCap}; передача до ${state.cfg.recharge} энергии за такт.`:type==='bioPack'?`Запас ${state.bio} / ${resourceCap(state,'bio')}`:`Запас ${state.water} / ${resourceCap(state,'water')}`}</p>${[1,2,3].filter(packs=>type!=='battery'||packs*size<=state.cfg.reserveCap).map(packs=>command({type,packs},`Купить ${packs*size} · ${packs*price} кр.`)).join('')}</section>`).join('')}</div><section class="panel fuel-panel"><div><h2>Топливо генератора</h2><p>${state.upgrades.generator?`${state.fuel} / ${state.cfg.fuelSize} · заправка при пустом баке`:'Сначала установите генератор в улучшениях.'}</p></div>${command({type:'fuel'},`Заправить · ${state.cfg.fuelPrice} кр.`)}</section>${forecast()}`;}
function restPage(){return `${pageHeading('Отдых','Пропустите рабочие такты или завершите смену.')}<div class="two-column"><section class="panel"><span class="eyebrow">Длительность</span><h2>Пауза диспетчера</h2><div class="rest-options">${[1,6,24].map(n=>`<button class="${ui.rest===n?'selected':''}" data-rest="${n}" aria-pressed="${ui.rest===n}"><strong>${n}</strong><span>такт.</span></button>`).join('')}</div><p>Производство и подзарядка работают. Пассажиры продолжают прибывать, а терпение уменьшается.</p><div class="warning">На станции ${active(state).length} пассажиров. Длительный отдых может привести к их уходу. Пропуск остановится при конце смены или партии.</div><button class="button primary full" data-action="rest" ${state.ended?'disabled':''}>Отдохнуть · пропустить ${ui.rest} такт.</button><hr><h3>Завершить смену</h3><p>Закрытие — 1 рабочий такт, затем ${state.cfg.sleepTicks} тактов сна. Оставшиеся гости уйдут. Содержание: ${state.cfg.upkeep} кр.</p><button class="button full" data-action="close" ${state.ended?'disabled':''}>Закрыть станцию и поспать</button></section><aside class="panel"><h2>Активные эффекты</h2><div class="effects-list"><div><b>Батарея</b><span>До +${state.cfg.recharge} энергии / такт · запас ${state.reserve}</span></div><div><b>Генератор</b><span>${state.upgrades.generator?`+${generatorYield(state)} / ${state.cfg.generatorPeriod} такта · топливо ${state.fuel}`:'Не установлен'}</span></div>${['bio','water'].map(k=>`<div><b>${k==='bio'?'Биосинтез':'Водосборник'}</b><span>${state.production[k]?`+${productionYield(state,k)} / ${state.cfg.period} такта за ${state.cfg.productionEnergy} энергии`:'Выключен'}</span></div>`).join('')}</div><p class="hint">Отдых не добавляет опыт сам по себе. XP начисляется за прибывших в пункт назначения пассажиров.</p></aside></div>`;}
function notifications(){const list=[];if(state.bio<20)list.push('Мало биоматериала — включите производство или пополните склад.');if(state.reserve<12)list.push('Заканчивается заряд батареи.');if(state.water<5)list.push('Мало воды для приема аквари.');if(state.credits<state.cfg.upkeep)list.push('Не хватает кредитов на содержание в конце смены.');for(const p of active(state).filter(p=>p.remaining<=4))list.push(`${p.name}: осталось ${p.remaining} такт. (${statusLabel(p).toLowerCase()}).`);return list;}
function render(){const pages={passengers:passengerPage,rooms:roomsPage,routes:routesPage,workshop:workshopPage,upgrades:upgradesPage,supply:supplyPage,rest:restPage};app.innerHTML=`${header()}<div class="shell">${sideNav()}<main id="main-content" tabindex="-1">${state.ended?`<section class="panel ending-banner">${resultHtml(false)}</section>`:''}${pages[ui.page]()}<footer><span>Осмотр и навигация бесплатны · действия занимают такты</span><button class="text-button" data-action="export">Отчет партии ↓</button></footer></main></div>`;}

function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openModal(content,wide=false){modal.className=wide?'wide':'';modal.innerHTML=content;if(!modal.open)modal.showModal();}
const modalHeader=(title,sub='')=>`<div class="modal-top"><div><span class="eyebrow">Пересадочная</span><h2>${title}</h2>${sub?`<p class="muted">${sub}</p>`:''}</div><button data-action="dismiss" class="icon-button" aria-label="Закрыть окно">×</button></div>`;
function intro(){openModal(`${modalHeader('Добро пожаловать на станцию','Шесть смен: развивайте станцию и отправляйте пассажиров.')}<div class="intro-art">${avatar('dry')}${avatar('water')}${avatar('gas')}</div><ol class="instructions"><li><b>Выберите пассажира.</b> Подготовьте комнату с нужной средой и примите его.</li><li><b>Подтвердите направление, затем отправьте рейс.</b> Каждое действие занимает один такт. Рейсы можно объединять по направлению.</li><li><b>Следите за энергией и терпением.</b> Батарея подзаряжает накопитель; производство тратит энергию.</li><li><b>Смена длится ${state.cfg.shiftTicks} такта.</b> Перед сном отправьте гостей и оставьте ${state.cfg.upkeep} кредитов на содержание.</li></ol><div class="info-box">Цель: ${state.cfg.target} отправок, без банкротства. Можно осматривать все бесплатно.</div><button class="action primary" data-action="dismiss"><span>Начать смену</span><span>Сразу к игре →</span></button>`);}
function help(){openModal(`${modalHeader('Как устроена станция')}<div class="help-grid"><section><h3>Пассажиры</h3><p>Прием стоит 1–10 био по индивидуальному запросу. У каждого гостя свое терпение. Очередь вмещает ${state.cfg.queueCap} гостей; при переполнении новый гость уходит без штрафа репутации. Просрочка в очереди: −1, в комнате: −2 репутации.</p><p>Терраны живут в сухой, аквари — в водной, аэриды — в газовой среде. Перестроить можно только пустую комнату. После отправки среда сохраняется.</p><p>Беженцы едут куда угодно, туристы выбирают из двух направлений, у дипломатов и торговцев только одна цель. Репутация открывает новые категории отдельно у каждой расы.</p></section><section><h3>Такты и энергия</h3><p>Осмотр и выбор объекта бесплатны. Прием, маршрут и отправка — три отдельных действия. Перелет занимает 1–3 такта; отправление входит в эту длительность. Оплата и опыт начисляются по прибытии. На последнем такте терпения еще можно помочь.</p><p>Запас энергии тратится на действия, заряд батареи постепенно пополняет его. Генератор расходует топливо. Во сне производство работает, но гости уходят.</p></section><section><h3>Прогресс</h3><p>XP открывает B и C, кредиты оплачивают снабжение, репутация открывает категории. Улучшения не нужны для победы. Звездочкой отмечены знакомые персонажи.</p></section><section><h3>Тестирование</h3><p>В «Балансе» можно изменить параметры новой партии. «Отчет» сохраняет все команды и ресурсы до и после такта. «Журнал» показывает события и результаты смен.</p><p>Настройки не меняют текущую партию. Такт проходит только после действия. Во вкладках мастерской доступны пайки, наборы комфорта и энергоячейки. Комнаты можно строить и улучшать; в рейсе летят несколько гостей одного направления.</p></section></div>`,true);}
function resultHtml(inModal=true){return `${inModal?modalHeader(state.ending==='win'?'План выполнен!':state.ending==='bankrupt'?'Станции не хватило средств':'Шесть смен позади'): `<h2>${state.ending==='win'?'План выполнен!':state.ending==='bankrupt'?'Банкротство':'Партия завершена'}</h2>`}<div class="result-number">${state.sent}<span>из ${state.cfg.target} нужных отправок</span></div><p>Кредиты: <b>${state.credits}</b> · ушли: <b>${state.lost}</b> · не приняты из-за раннего закрытия: <b>${state.skipped}</b>.</p><div class="info-box">${state.sent>=state.cfg.target?'✓':'○'} ${state.cfg.target} отправок<br>${state.upgrades.generator?'✓':'○'} Генератор установлен<br>${state.stories.neri.gift&&state.stories.ro.gift?'✓':'○'} Обе истории с благодарностью</div><p class="hint">Выгрузите отчет, чтобы сравнить партии и найти места, где не хватало времени или ресурсов.</p><button class="action primary" data-action="export">Скачать отчет партии</button><button class="action" data-action="new">Новая партия</button>`;}
function summary(){const sum=state.summaries.at(-1);openModal(`${modalHeader(`Смена ${sum.shift} завершена`)}<div class="summary-stats"><div><strong>${sum.shiftSent}</strong><span>отправлено</span></div><div><strong>${sum.shiftLost}</strong><span>ушли</span></div><div><strong>${sum.credits}</strong><span>кредитов</span></div></div><p>Станция отдохнула ${state.cfg.sleepTicks} тактов. Содержание оплачено: ${state.cfg.upkeep} кредитов. Производство и подзарядка учтены.</p><div class="info-box">Следующая смена: ${state.shift} из 6. Пассажиры уже в очереди.</div><button class="action primary" data-action="dismiss">Продолжить смену ${state.shift} →</button>`);}
function journal(){openModal(`${modalHeader('Журнал станции',`Отправлено ${state.sent} · мировой такт ${state.world} · поток ${state.seed}`)}<h3>Смены</h3><div class="summary-list">${state.summaries.length?state.summaries.map(s=>`<div>Смена ${s.shift}: ${s.shiftSent} отправок · ${s.shiftLost} потерь · ${s.credits} кр.</div>`).join(''):'Пока нет завершенных смен.'}</div><h3>События</h3><div class="log-list">${state.log.length?state.log.slice().reverse().map(e=>`<details><summary><span>С${e.shift} / ${e.tick}</span> ${esc(e.label)}</summary><p>${esc(e.events.join(' • ')||'Ресурсы не изменились.')}</p><p class="hint">Кредиты ${e.before.credits} → ${e.after.credits}; энергия ${e.before.energy} → ${e.after.energy}; заряд ${e.before.reserve} → ${e.after.reserve}</p></details>`).join(''):'Первое действие еще не совершено.'}</div>`,true);}
function settings(){settingsDraft??={...state.cfg};openModal(`${modalHeader('Настройки баланса','Применяются только к новой партии. Текущая игра пока сохраняется.')}<form id="balance-form"><div class="settings-groups">${[...new Set(Object.values(FIELDS).map(v=>v[4]))].map((group,i)=>`<details ${i===0?'open':''}><summary>${group}</summary><div class="settings-fields">${Object.entries(FIELDS).filter(([,v])=>v[4]===group).map(([k,[,min,max,label]])=>`<label>${esc(label)}<input name="${k}" type="number" min="${min}" max="${max}" step="1" value="${settingsDraft[k]}" required></label>`).join('')}</div></details>`).join('')}</div><p id="settings-error" role="alert"></p><div class="settings-actions"><button type="button" data-action="defaults">Базовый баланс</button><button type="button" data-action="export-config">Экспорт настроек</button><button type="button" class="primary" data-action="apply-config">Новая партия с настройками</button></div></form>`,true);}
function readSettings(){const form=document.querySelector('#balance-form');if(!form)return settingsDraft;const cfg=Object.fromEntries(Object.keys(FIELDS).map(k=>[k,Number(form.elements.namedItem(k).value)]));const error=validateConfig(cfg);document.querySelector('#settings-error').textContent=error;if(error)return null;settingsDraft=cfg;return cfg;}
function confirmNew(cfg=state.cfg){openModal(`${modalHeader('Начать новую партию?')}<p>Текущая партия будет заменена. При необходимости сначала сохраните отчет.</p><button class="action" data-action="export">Скачать отчет текущей партии</button><button class="action primary" id="confirm-new">Начать новую партию</button><button class="action" data-action="dismiss">Вернуться</button>`);document.querySelector('#confirm-new').onclick=()=>{state=newGame(cfg);ui.page='passengers';ui.room=0;ui.dialog={};ui.noticeRead=0;selected={kind:'guest',id:1};helpChoice=false;save();modal.close();render();toast('Новая партия. Пассажиры уже ждут.');};}
function closeConfirm(){if(state.ended)return;const guests=active(state);openModal(`${modalHeader('Закрыть станцию и поспать?')}<p>Пройдет 1 рабочий такт и ${state.cfg.sleepTicks} тактов сна. Содержание: ${state.cfg.upkeep} кредитов. Не наступившие прибытия будут пропущены.</p>${guests.length?`<div class="warning"><b>Эти пассажиры уйдут:</b>${guests.map(p=>`<p>${esc(p.name)} · −${p.status==='room'?2:1} репутации ${RACES[p.race].name.toLowerCase()}</p>`).join('')}</div>`:'<div class="info-box">Все комнаты и очередь свободны. Никто не потеряет репутацию.</div>'}<button class="action primary" data-action="confirm-close">Закрыть и поспать</button><button class="action" data-action="dismiss">Остаться на станции</button>`);}

function changePage(page){if(!PAGES.some(p=>p[0]===page))return;ui.page=page;render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main-content').focus({preventScroll:true});}
function chooseGuest(id){const p=state.guests.find(g=>g.id===id&&['queue','room'].includes(g.status));if(!p)return;selected={kind:'guest',id:p.id};helpChoice=false;ui.page='passengers';save();render();}
function confirmCommand(cmd){const check=inspect(state,cmd);if(!check.ok){toast(check.reason);return;}const preview=act(state,cmd),losses=preview.events.filter(e=>/истек|эвакуация|закрытие станции|переполнена/.test(e.toLowerCase()));openModal(`${modalHeader('Подтвердить действие',check.label)}<div class="cost-box"><b>${fmtCost(check.cost)||'Без затрат ресурсов'}</b><span>1 рабочий такт</span></div>${cmd.type==='depart'?`<p>${cmd.guests.map(id=>esc(state.guests.find(g=>g.id===id).name)).join(', ')}. Комнаты освободятся сразу. Оплата поступит по прибытии.</p>`:''}${cmd.type==='refuse'?'<div class="warning">Гость уйдет. Репутация его расы уменьшится на 1.</div>':''}${losses.length?`<div class="warning">${losses.map(esc).join('<br>')}</div>`:''}${preview.state.shift!==state.shift?'<div class="warning">Это действие завершит смену и запустит сон с оплатой содержания.</div>':''}<button class="action primary" id="confirm-action">Подтвердить</button><button class="action" data-action="dismiss">Отмена</button>`);document.querySelector('#confirm-action').onclick=()=>{modal.close();run(cmd);};}
function run(cmd){const prevShift=state.shift,guest=state.guests.find(p=>p.id===cmd.guest);const r=act(state,cmd);if(!r.ok){toast(r.reason);return;}state=r.state;
 if(cmd.type==='accept'){selected={kind:'guest',id:cmd.guest};ui.page='passengers';}
 if(cmd.type==='route'){ui.route=cmd.route;ui.manifest=[...new Set([...ui.manifest,cmd.guest])];helpChoice=false;}
 if(cmd.type==='send'||cmd.type==='depart'||cmd.type==='refuse'||state.shift!==prevShift){const p=active(state)[0];selected=p?{kind:'guest',id:p.id}:{kind:'guest',id:null};helpChoice=false;}
 if(cmd.type==='build')ui.room=state.rooms.length-1;
 save();render();toast(r.label+(cmd.type==='craft'?' · готово':cmd.type==='accept'?` · ${guest.name} размещен`:''));
 if(state.ended)openModal(resultHtml());else if(state.shift!==prevShift)summary();
}
function preview(button){const box=document.querySelector('#forecast');if(!box||!button?.dataset.cmd||button.disabled)return;const result=act(state,JSON.parse(button.dataset.cmd));if(!result.ok)return;const deltas=['credits','energy','reserve','bio','water'].filter(k=>result.state[k]!==state[k]).map(k=>`${{credits:'Кредиты',energy:'Энергия',reserve:'Заряд',bio:'Био',water:'Вода'}[k]}: ${state[k]} → ${result.state[k]}`);box.innerHTML=`<b>После действия</b><span>${esc(deltas.join(' · ')||'Запасы не изменятся')}</span><span>${result.state.shift!==state.shift?'Смена завершится.':'Пройдет 1 такт.'}</span>`;}
function chooseRoom(){const p=currentGuest();if(!p)return;openModal(`${modalHeader('Выбрать комнату',`${p.name} · ${RACES[p.race].medium} среда`)}${state.rooms.map((m,i)=>command({type:'accept',guest:p.id,room:i},`Комната ${i+1} · ${RACES[m].medium} · ур. ${state.roomLevels[i]}${occupant(state,i)?' · занята':''}`)).join('')}<button class="button full" data-modal-page="rooms">Открыть комнаты и перестроить →</button>`);}
function buildRoom(){openModal(`${modalHeader('Построить новую комнату','Выберите среду нового жилого модуля.')}<p>Одно дополнительное место. Текущая вместимость ${state.rooms.length} / ${state.cfg.maxRooms} комнат.</p>${Object.keys(RACES).map(m=>command({type:'build',medium:m},RACES[m].medium+' комната')).join('')}`);}
function roomInfo(){const i=ui.room,p=occupant(state,i);openModal(`${modalHeader('Комната '+(i+1))}${roomArt(state.rooms[i],p)}<div class="facts"><div><span>Среда</span><b>${RACES[state.rooms[i]].medium}</b></div><div><span>Уровень</span><b>${state.roomLevels[i]} / 2</b></div><div><span>Вместимость</span><b>1 пассажир</b></div><div><span>Статус</span><b>${p?'Занята: '+esc(p.name):'Свободна'}</b></div></div><p>${state.roomLevels[i]>1?'Прием на 1 био дешевле; срок размещения на 2 такта больше.':'Базовые расход и срок размещения.'}</p>`);}
function addPassenger(){const list=state.guests.filter(p=>p.status==='room');openModal(`${modalHeader('Добавить пассажира',DESTINATIONS[ui.route])}${list.length?list.map(p=>`<div class="add-person"><b>${esc(p.name)}</b><span>${p.route?'Маршрут '+p.route:'Без маршрута'} · ${p.remaining} такт.</span>${p.route===ui.route?`<button class="button" data-add-manifest="${p.id}" ${ui.manifest.includes(p.id)?'disabled':''}>${ui.manifest.includes(p.id)?'Уже в списке':'Добавить в список'}</button>`:command({type:'route',guest:p.id,route:ui.route,help:false},'Оформить маршрут и добавить')}</div>`).join(''):'<p>Сначала разместите пассажира в комнате.</p>'}<button class="button full" data-modal-page="passengers">Перейти к пассажирам</button>`);}
function restConfirm(){const ticks=Math.min(ui.rest,state.cfg.shiftTicks-state.tick);let previewState=state,losses=[];for(let i=0;i<ticks&&!previewState.ended;i++){const r=act(previewState,{type:'wait'});losses.push(...r.events.filter(e=>/истек|эвакуация|закрытие станции|переполнена/.test(e.toLowerCase())));previewState=r.state;}
 openModal(`${modalHeader('Отдохнуть '+ticks+' такт.','Пассажиры и производство продолжат жить по расписанию.')}<p>После отдыха: энергия ${state.energy} → ${previewState.energy}; био ${state.bio} → ${previewState.bio}; вода ${state.water} → ${previewState.water}.</p>${ticks===state.cfg.shiftTicks-state.tick?`<div class="warning">Смена завершится, затем пройдет ${state.cfg.sleepTicks} тактов сна. Содержание: ${state.cfg.upkeep} кр.</div>`:''}${losses.length?`<div class="warning"><b>Пассажиры могут уйти:</b><p>${losses.map(esc).join('<br>')}</p></div>`:''}<button class="action primary" id="confirm-rest">Отдохнуть</button><button class="action" data-action="dismiss">Отмена</button>`);
 document.querySelector('#confirm-rest').onclick=()=>{modal.close();const shift=state.shift;let elapsed=0;for(let i=0;i<ticks&&!state.ended&&state.shift===shift;i++){state=act(state,{type:'wait'}).state;elapsed++;}helpChoice=false;save();render();toast(`Пропущено ${elapsed} рабочих такт.`);if(state.ended)openModal(resultHtml());else if(state.shift!==shift)summary();};
}
function settingsMenu(){openModal(`${modalHeader('Настройки')}<button class="action" data-action="settings">Баланс новой партии</button><button class="action" data-action="help">Как играть</button><button class="action" data-action="export">Скачать отчет партии</button><button class="action" data-action="new">Начать новую партию</button>`);}
function reputation(){openModal(`${modalHeader('Репутация рас','Каждая раса оценивает станцию отдельно.')}<div class="rep-grid">${Object.entries(RACES).map(([k,r])=>`<section>${avatar(k)}<h3>${r.name}</h3><b>${state.rep[k]}</b><p>Открыто: ${CATEGORIES[state.unlocked[k]]}</p></section>`).join('')}</div><p>Туристы: ${state.cfg.repTourist}; дипломаты: ${state.cfg.repDiplomat}; торговцы: ${state.cfg.repTrader}. Личное отношение указано в карточке гостя.</p>`);}
document.addEventListener('click',event=>{
 const el=event.target.closest('button');if(!el||el.disabled)return;
 if(el.dataset.cmd){const cmd=JSON.parse(el.dataset.cmd);if(['wait','toggle'].includes(cmd.type)){if(modal.open)modal.close();run(cmd);}else confirmCommand(cmd);return;}
 if(el.dataset.page){changePage(el.dataset.page);return;}
 if(el.dataset.modalPage){modal.close();changePage(el.dataset.modalPage);return;}
 if(el.dataset.select){chooseGuest(Number(el.dataset.select.split(':')[1]));return;}
 if(el.dataset.guest){chooseGuest(Number(el.dataset.guest));return;}
 if(el.dataset.room!==undefined){ui.room=Number(el.dataset.room);render();return;}
 if(el.dataset.route){ui.route=el.dataset.route;render();return;}
 if(el.dataset.tab){const [kind,v]=el.dataset.tab.split(':');if(kind==='work'){ui.workTab=v;ui.recipe=v==='Оборудование'?'cell':'ration';}else ui.upgradeTab=v;render();return;}
 if(el.dataset.recipe){ui.recipe=el.dataset.recipe;render();return;}
 if(el.dataset.producer){ui.producer=el.dataset.producer;render();return;}
 if(el.dataset.rest){ui.rest=Number(el.dataset.rest);render();return;}
 if(el.dataset.addManifest){ui.manifest=[...new Set([...ui.manifest,Number(el.dataset.addManifest)])];modal.close();render();return;}
 if(el.dataset.talk){const p=currentGuest();if(!p)return;ui.dialog[p.id]=el.dataset.talk==='needs'?`Мне нужна ${RACES[p.race].medium.toLowerCase()} среда и ${p.bioNeed} биоматериала на размещение. ${p.status==='queue'?`Готов ждать еще ${p.remaining} такт.`:'Комната уже подготовлена.'}`:`Мой маршрут: ${allowedRoutes(state,p).map(k=>DESTINATIONS[k]).join(' или ')}. ${p.route?'Направление уже подтверждено.':'Помогите выбрать рейс.'}`;render();return;}
 const action=el.dataset.action;
 if(action==='dismiss')modal.close();
 if(action==='choose-room')chooseRoom();
 if(action==='choose-route'){const p=currentGuest();if(p){ui.route=p.route||allowedRoutes(state,p)[0];ui.manifest=p.route?[p.id]:[];}changePage('routes');}
 if(action==='help-story'){helpChoice=!helpChoice;render();}
 if(action==='build-room')buildRoom();if(action==='room-info')roomInfo();if(action==='add-passenger')addPassenger();
 if(action==='rest')restConfirm();if(action==='newest'){const p=active(state).at(-1);if(p)chooseGuest(p.id);}
 if(action==='notifications'){const notes=notifications();openModal(`${modalHeader('Сообщения станции')}${notes.length?notes.map(x=>`<div class="warning">${esc(x)}</div>`).join(''):'<div class="info-box">Срочных сообщений нет.</div>'}`);}
 if(action==='reputation')reputation();if(action==='settings-menu')settingsMenu();
 if(action==='help')help();if(action==='journal')journal();if(action==='settings')settings();
 if(action==='export')download(`station-report-${state.shift}-${state.log.length}.json`,{version:VERSION,exportedAt:new Date().toISOString(),state,selected});
 if(action==='new')confirmNew();if(action==='close')closeConfirm();if(action==='confirm-close'){modal.close();run({type:'close'});}
 if(action==='defaults'){settingsDraft={...DEFAULTS};settings();}
 if(action==='export-config'){const cfg=readSettings();if(cfg)download('station-balance.json',{version:VERSION,config:cfg});}
 if(action==='apply-config'){const cfg=readSettings();if(cfg)confirmNew(cfg);}
});
document.addEventListener('change',event=>{if(event.target.dataset.manifest){const id=Number(event.target.dataset.manifest);ui.manifest=event.target.checked?[...new Set([...ui.manifest,id])]:ui.manifest.filter(x=>x!==id);render();}});
document.addEventListener('submit',event=>{if(event.target.id==='balance-form'){event.preventDefault();readSettings();}});
document.addEventListener('mouseover',event=>preview(event.target.closest('[data-cmd]')));
document.addEventListener('focusin',event=>preview(event.target.closest('[data-cmd]')));
render();if(!loaded)intro();else if(state.ended)openModal(resultHtml());else toast('Партия восстановлена. Новый интерфейс готов.');if(storageWarning)toast(storageWarning);
